insert into public.courses (slug, title, category, color, summary, price_cop, free_modules, sources, lang) values
  ('ciencia-de-datos', 'Ciencia de Datos', 'Datos', '#1E88E5', 'Convierte datos en decisiones: Python, estadística, limpieza, visualización, machine learning y comunicación de resultados con proyectos reales.', 89900, 5, '[{"title": "Documentación de pandas", "publisher": "pandas – NumFOCUS", "url": "https://pandas.pydata.org/docs/", "use": "Análisis de datos con Python"}, {"title": "Guía de usuario de scikit-learn", "publisher": "scikit-learn", "url": "https://scikit-learn.org/stable/user_guide.html", "use": "Modelos de machine learning"}, {"title": "Portal de Datos Abiertos de Colombia", "publisher": "MinTIC", "url": "https://www.datos.gov.co/", "use": "Conjuntos de datos reales para practicar"}]'::jsonb, null),
  ('estadistica', 'Estadística', 'Datos', '#3949AB', 'Aprende a recolectar, describir e interpretar datos: probabilidad, inferencia, regresión, diseño de experimentos y software estadístico.', 89900, 5, '[{"title": "Introducción a la estadística (libro gratuito en español)", "publisher": "OpenStax – Rice University", "url": "https://openstax.org/details/books/introducci%C3%B3n-estad%C3%ADstica", "use": "Texto guía de estadística"}, {"title": "Estadística y probabilidad en Khan Academy", "publisher": "Khan Academy", "url": "https://es.khanacademy.org/math/statistics-probability", "use": "Ejercicios y videos gratuitos"}, {"title": "DANE", "publisher": "Departamento Administrativo Nacional de Estadística", "url": "https://www.dane.gov.co/", "use": "Estadísticas oficiales de Colombia"}]'::jsonb, null),
  ('analisis-de-datos', 'Análisis de Datos', 'Datos', '#00897B', 'Responde preguntas de negocio con datos: Excel, SQL, Power BI, Python, métricas, dashboards y presentación de hallazgos.', 89900, 5, '[{"title": "Documentación de pandas", "publisher": "pandas – NumFOCUS", "url": "https://pandas.pydata.org/docs/", "use": "Análisis de datos con Python"}, {"title": "Documentación de Power BI", "publisher": "Microsoft Learn", "url": "https://learn.microsoft.com/es-es/power-bi/", "use": "Tableros e inteligencia de negocios"}, {"title": "Portal de Datos Abiertos de Colombia", "publisher": "MinTIC", "url": "https://www.datos.gov.co/", "use": "Conjuntos de datos reales para practicar"}]'::jsonb, null),
  ('aprendizaje-automatico', 'Aprendizaje Automático (Machine Learning)', 'Datos', '#5E35B1', 'Construye modelos que aprenden de los datos: algoritmos supervisados y no supervisados, redes neuronales, evaluación y puesta en producción.', 89900, 5, '[{"title": "Curso intensivo de machine learning", "publisher": "Google for Developers", "url": "https://developers.google.com/machine-learning/crash-course?hl=es-419", "use": "Curso gratuito de aprendizaje automático"}, {"title": "Guía de usuario de scikit-learn", "publisher": "scikit-learn", "url": "https://scikit-learn.org/stable/user_guide.html", "use": "Modelos de machine learning"}]'::jsonb, null),
  ('mineria-de-datos', 'Minería de Datos', 'Datos', '#6D4C41', 'Descubre patrones ocultos en grandes bases de datos: preprocesamiento, clasificación, agrupamiento, reglas de asociación, minería de texto y web.', 89900, 5, '[{"title": "Guía de usuario de scikit-learn", "publisher": "scikit-learn", "url": "https://scikit-learn.org/stable/user_guide.html", "use": "Modelos de machine learning"}, {"title": "Documentación de pandas", "publisher": "pandas – NumFOCUS", "url": "https://pandas.pydata.org/docs/", "use": "Análisis de datos con Python"}, {"title": "Portal de Datos Abiertos de Colombia", "publisher": "MinTIC", "url": "https://www.datos.gov.co/", "use": "Conjuntos de datos reales para practicar"}]'::jsonb, null),
  ('inteligencia-de-negocios', 'Inteligencia de Negocios (BI)', 'Datos', '#F9A825', 'Transforma datos empresariales en tableros e indicadores: modelado dimensional, ETL, data warehouse, Power BI, KPI y cultura de datos.', 89900, 5, '[{"title": "Documentación de Power BI", "publisher": "Microsoft Learn", "url": "https://learn.microsoft.com/es-es/power-bi/", "use": "Tableros e inteligencia de negocios"}, {"title": "Portal de Datos Abiertos de Colombia", "publisher": "MinTIC", "url": "https://www.datos.gov.co/", "use": "Conjuntos de datos reales para practicar"}]'::jsonb, null),
  ('econometria', 'Econometría', 'Datos', '#2E7D32', 'Mide relaciones económicas con datos: regresión, inferencia, series de tiempo, datos de panel, causalidad y evaluación de políticas.', 89900, 5, '[{"title": "Documentación de statsmodels", "publisher": "statsmodels", "url": "https://www.statsmodels.org/stable/index.html", "use": "Modelos econométricos en Python"}, {"title": "Banco de la República", "publisher": "Banco de la República de Colombia", "url": "https://www.banrep.gov.co/es", "use": "Indicadores económicos y financieros"}, {"title": "DANE", "publisher": "Departamento Administrativo Nacional de Estadística", "url": "https://www.dane.gov.co/", "use": "Estadísticas oficiales de Colombia"}]'::jsonb, null),
  ('bases-de-datos', 'Bases de Datos', 'Datos', '#00695C', 'Diseña y administra bases de datos: modelado, SQL, normalización, PostgreSQL, rendimiento, seguridad, NoSQL y bases de datos en la nube.', 89900, 5, '[{"title": "Tutorial de PostgreSQL", "publisher": "PostgreSQL Global Development Group", "url": "https://www.postgresql.org/docs/current/tutorial.html", "use": "SQL y bases de datos relacionales"}, {"title": "Documentación de MongoDB", "publisher": "MongoDB", "url": "https://www.mongodb.com/docs/", "use": "Bases de datos NoSQL"}]'::jsonb, null),
  ('analitica-predictiva', 'Analítica Predictiva', 'Datos', '#C62828', 'Anticípate a lo que viene: pronósticos, modelos de riesgo, fuga de clientes, demanda y scoring, con validación y uso responsable.', 89900, 5, '[{"title": "Guía de usuario de scikit-learn", "publisher": "scikit-learn", "url": "https://scikit-learn.org/stable/user_guide.html", "use": "Modelos de machine learning"}, {"title": "Curso intensivo de machine learning", "publisher": "Google for Developers", "url": "https://developers.google.com/machine-learning/crash-course?hl=es-419", "use": "Curso gratuito de aprendizaje automático"}, {"title": "Portal de Datos Abiertos de Colombia", "publisher": "MinTIC", "url": "https://www.datos.gov.co/", "use": "Conjuntos de datos reales para practicar"}]'::jsonb, null),
  ('bioestadistica', 'Bioestadística', 'Datos', '#AD1457', 'Estadística para la salud y las ciencias de la vida: diseño de estudios, pruebas, supervivencia, ensayos clínicos y epidemiología.', 89900, 5, '[{"title": "Introducción a la estadística (libro gratuito en español)", "publisher": "OpenStax – Rice University", "url": "https://openstax.org/details/books/introducci%C3%B3n-estad%C3%ADstica", "use": "Texto guía de estadística"}, {"title": "The R Project for Statistical Computing", "publisher": "R Foundation", "url": "https://www.r-project.org/", "use": "Lenguaje R para estadística"}, {"title": "Instituto Nacional de Salud", "publisher": "Gobierno de Colombia", "url": "https://www.ins.gov.co/", "use": "Vigilancia en salud pública y laboratorios"}]'::jsonb, null),
  ('pedagogia', 'Pedagogía', 'Educación', '#6A1B9A', 'Comprende cómo se aprende y cómo se enseña: teorías pedagógicas, planeación, evaluación, ambientes de aprendizaje e investigación educativa.', 89900, 5, '[{"title": "Ley 115 de 1994 (Ley General de Educación)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_0115_1994.html", "use": "Marco legal de la educación"}, {"title": "Colombia Aprende", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/", "use": "Recursos y orientaciones para docentes"}, {"title": "Educación en la UNESCO", "publisher": "UNESCO", "url": "https://www.unesco.org/es/education", "use": "Políticas y tendencias educativas"}]'::jsonb, null),
  ('educacion-infantil', 'Educación Infantil', 'Educación', '#F06292', 'Acompaña el desarrollo de niñas y niños de 0 a 6 años: desarrollo integral, juego, arte, literatura, exploración del medio y trabajo con familias.', 89900, 5, '[{"title": "Ley 1804 de 2016 (De Cero a Siempre)", "publisher": "Normograma de la CRA", "url": "https://normas.cra.gov.co/gestor/docs/ley_1804_2016.htm", "use": "Política de primera infancia"}, {"title": "ICBF", "publisher": "Instituto Colombiano de Bienestar Familiar", "url": "https://www.icbf.gov.co/", "use": "Primera infancia y protección"}, {"title": "UNICEF Colombia", "publisher": "UNICEF", "url": "https://www.unicef.org/colombia/", "use": "Derechos de la niñez"}]'::jsonb, null),
  ('educacion-primaria', 'Educación Primaria', 'Educación', '#43A047', 'Enseña en los grados 1.º a 5.º: lectoescritura, matemáticas, ciencias, sociales, arte y convivencia con estrategias activas.', 89900, 5, '[{"title": "Ley 115 de 1994 (Ley General de Educación)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_0115_1994.html", "use": "Marco legal de la educación"}, {"title": "Derechos Básicos de Aprendizaje de Lenguaje", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/recurso-coleccion/derechos-basicos-de-aprendizaje-dba-lenguaje", "use": "Referentes curriculares"}, {"title": "ICFES", "publisher": "Instituto Colombiano para la Evaluación de la Educación", "url": "https://www.icfes.gov.co/", "use": "Pruebas Saber y evaluación"}]'::jsonb, null),
  ('educacion-secundaria', 'Educación Secundaria', 'Educación', '#1565C0', 'Enseña a adolescentes de 6.º a 11.º: desarrollo adolescente, didáctica por áreas, orientación vocacional, Saber 11 y convivencia.', 89900, 5, '[{"title": "Ley 115 de 1994 (Ley General de Educación)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_0115_1994.html", "use": "Marco legal de la educación"}, {"title": "ICFES", "publisher": "Instituto Colombiano para la Evaluación de la Educación", "url": "https://www.icfes.gov.co/", "use": "Pruebas Saber y evaluación"}, {"title": "Colombia Aprende", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/", "use": "Recursos y orientaciones para docentes"}]'::jsonb, null),
  ('educacion-especial', 'Educación Especial', 'Educación', '#00838F', 'Apoya a estudiantes con discapacidad y talentos excepcionales: tipos de discapacidad, evaluación, apoyos, comunicación aumentativa y PIAR.', 89900, 5, '[{"title": "Ley Estatutaria 1618 de 2013", "publisher": "Normograma del INVIMA", "url": "https://normograma.invima.gov.co/compilacion/docs/ley_1618_2013.htm", "use": "Derechos de las personas con discapacidad"}, {"title": "Instituto Nacional para Ciegos (INCI)", "publisher": "Gobierno de Colombia", "url": "https://www.inci.gov.co/", "use": "Discapacidad visual"}, {"title": "Recursos educativos accesibles para comunidades sordas", "publisher": "Colombia Aprende", "url": "https://colombiaaprende.edu.co/contenidos/plataforma/recursos-educativos-accesibles-para-comunidades-sordas", "use": "Discapacidad auditiva"}]'::jsonb, null),
  ('educacion-inclusiva', 'Educación Inclusiva', 'Educación', '#7CB342', 'Construye una escuela para todas y todos: barreras, diseño universal para el aprendizaje, PIAR, interculturalidad, género y cultura inclusiva.', 89900, 5, '[{"title": "Pautas del Diseño Universal para el Aprendizaje", "publisher": "CAST", "url": "https://udlguidelines.cast.org/", "use": "Diseño universal para el aprendizaje"}, {"title": "Ley Estatutaria 1618 de 2013", "publisher": "Normograma del INVIMA", "url": "https://normograma.invima.gov.co/compilacion/docs/ley_1618_2013.htm", "use": "Derechos de las personas con discapacidad"}, {"title": "Educación en la UNESCO", "publisher": "UNESCO", "url": "https://www.unesco.org/es/education", "use": "Políticas y tendencias educativas"}]'::jsonb, null),
  ('didactica', 'Didáctica', 'Educación', '#EF6C00', 'Domina el arte de enseñar: transposición didáctica, secuencias, estrategias, recursos, evaluación y didácticas específicas por área.', 89900, 5, '[{"title": "Colombia Aprende", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/", "use": "Recursos y orientaciones para docentes"}, {"title": "Derechos Básicos de Aprendizaje de Lenguaje", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/recurso-coleccion/derechos-basicos-de-aprendizaje-dba-lenguaje", "use": "Referentes curriculares"}, {"title": "Pautas del Diseño Universal para el Aprendizaje", "publisher": "CAST", "url": "https://udlguidelines.cast.org/", "use": "Diseño universal para el aprendizaje"}]'::jsonb, null),
  ('psicopedagogia', 'Psicopedagogía', 'Educación', '#8E24AA', 'Comprende y apoya los procesos de aprendizaje: evaluación psicopedagógica, dificultades, intervención, orientación y trabajo con familias.', 89900, 5, '[{"title": "American Psychological Association", "publisher": "APA", "url": "https://www.apa.org/", "use": "Psicología y aprendizaje"}, {"title": "Pautas del Diseño Universal para el Aprendizaje", "publisher": "CAST", "url": "https://udlguidelines.cast.org/", "use": "Diseño universal para el aprendizaje"}, {"title": "Colombia Aprende", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/", "use": "Recursos y orientaciones para docentes"}]'::jsonb, null),
  ('administracion-educativa', 'Administración Educativa', 'Educación', '#455A64', 'Dirige instituciones educativas: gestión directiva, académica, administrativa y comunitaria, PEI, calidad, finanzas y liderazgo.', 89900, 5, '[{"title": "Ley 115 de 1994 (Ley General de Educación)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_0115_1994.html", "use": "Marco legal de la educación"}, {"title": "ICFES", "publisher": "Instituto Colombiano para la Evaluación de la Educación", "url": "https://www.icfes.gov.co/", "use": "Pruebas Saber y evaluación"}, {"title": "Colombia Aprende", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/", "use": "Recursos y orientaciones para docentes"}]'::jsonb, null),
  ('tecnologia-educativa', 'Tecnología Educativa', 'Educación', '#0277BD', 'Integra la tecnología con sentido pedagógico: modelos TPACK y SAMR, herramientas digitales, recursos abiertos, IA y diseño de experiencias.', 89900, 5, '[{"title": "Colombia Aprende", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/", "use": "Recursos y orientaciones para docentes"}, {"title": "Creative Commons", "publisher": "Creative Commons", "url": "https://creativecommons.org/", "use": "Licencias abiertas para recursos educativos"}, {"title": "Recomendación sobre la ética de la IA", "publisher": "UNESCO", "url": "https://www.unesco.org/es/artificial-intelligence/recommendation-ethics", "use": "IA responsable en educación"}]'::jsonb, null),
  ('educacion-bilingue', 'Educación Bilingüe', 'Educación', '#D84315', 'Enseña en dos lenguas: bilingüismo, adquisición de segundas lenguas, CLIL/AICLE, enfoques comunicativos, evaluación y programas bilingües.', 89900, 5, '[{"title": "Marco Común Europeo de Referencia (MCER)", "publisher": "Consejo de Europa", "url": "https://www.coe.int/en/web/common-european-framework-reference-languages", "use": "Niveles de lengua"}, {"title": "LearnEnglish", "publisher": "British Council", "url": "https://learnenglish.britishcouncil.org/", "use": "Recursos para enseñar inglés"}, {"title": "Colombia Aprende", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/", "use": "Recursos y orientaciones para docentes"}]'::jsonb, null),
  ('educacion-virtual', 'Educación Virtual', 'Educación', '#00ACC1', 'Diseña, enseña y gestiona cursos en línea: modalidades, aulas virtuales, tutoría, contenidos multimedia, evaluación y calidad.', 89900, 5, '[{"title": "Documentación de Moodle", "publisher": "Moodle", "url": "https://docs.moodle.org/", "use": "Aulas virtuales"}, {"title": "Pautas de accesibilidad WCAG", "publisher": "W3C", "url": "https://www.w3.org/WAI/standards-guidelines/wcag/es", "use": "Accesibilidad digital"}, {"title": "Creative Commons", "publisher": "Creative Commons", "url": "https://creativecommons.org/", "use": "Licencias abiertas para recursos educativos"}]'::jsonb, null),
  ('orientacion-escolar', 'Orientación Escolar', 'Educación', '#5D4037', 'Acompaña el bienestar y el proyecto de vida de los estudiantes: orientación socio-ocupacional, convivencia, rutas de atención y trabajo con familias.', 89900, 5, '[{"title": "Ley 1620 de 2013 (convivencia escolar)", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_1620_2013.html", "use": "Sistema Nacional de Convivencia Escolar"}, {"title": "ICBF", "publisher": "Instituto Colombiano de Bienestar Familiar", "url": "https://www.icbf.gov.co/", "use": "Primera infancia y protección"}, {"title": "Colombia Aprende", "publisher": "Ministerio de Educación Nacional", "url": "https://colombiaaprende.edu.co/", "use": "Recursos y orientaciones para docentes"}]'::jsonb, null),
