  ('ingenieria-electronica', 'Ingeniería Electrónica', 'Ingeniería', '#00897B', 'Diseña circuitos y sistemas electrónicos: componentes, electrónica analógica y digital, microcontroladores, señales, control e instrumentación.', 89900, 5, '[{"title": "Textbook for Electrical Engineering & Electronics", "publisher": "All About Circuits", "url": "https://www.allaboutcircuits.com/textbook/", "use": "Circuitos y electrónica"}, {"title": "Documentación de Arduino", "publisher": "Arduino", "url": "https://docs.arduino.cc/", "use": "Microcontroladores y prototipos"}, {"title": "Simulaciones PhET", "publisher": "Universidad de Colorado Boulder", "url": "https://phet.colorado.edu/es/", "use": "Simulaciones interactivas"}]'::jsonb, null),
  ('ingenieria-electrica', 'Ingeniería Eléctrica', 'Ingeniería', '#F9A825', 'Genera, transporta y usa la energía eléctrica: circuitos, máquinas eléctricas, sistemas de potencia, instalaciones, protecciones y RETIE.', 89900, 5, '[{"title": "Ministerio de Minas y Energía", "publisher": "Gobierno de Colombia", "url": "https://www.minenergia.gov.co/", "use": "Reglamentos técnicos como el RETIE"}, {"title": "XM – Operador del mercado eléctrico", "publisher": "XM S.A. E.S.P.", "url": "https://www.xm.com.co/", "use": "Operación del sistema eléctrico"}, {"title": "UPME", "publisher": "Unidad de Planeación Minero Energética", "url": "https://www.upme.gov.co/", "use": "Planeación energética y minera"}]'::jsonb, null),
