  ('ingenieria-civil', 'Ingeniería Civil', 'Ingeniería', '#795548', 'Proyecta y construye infraestructura: topografía, materiales, estructuras, suelos, hidráulica, vías, construcción y la norma sismorresistente NSR-10.', 89900, 5, '[{"title": "Ministerio de Vivienda (NSR-10)", "publisher": "Gobierno de Colombia", "url": "https://www.minvivienda.gov.co/", "use": "Reglamento sismorresistente"}, {"title": "Geología de Colombia (libro)", "publisher": "Servicio Geológico Colombiano", "url": "https://www2.sgc.gov.co/LibroGeologiaColombia/Paginas/Inicio.aspx", "use": "Geología del territorio colombiano"}, {"title": "IGAC", "publisher": "Instituto Geográfico Agustín Codazzi", "url": "https://www.igac.gov.co/", "use": "Cartografía y topografía"}]'::jsonb, null),
  ('ingenieria-mecanica', 'Ingeniería Mecánica', 'Ingeniería', '#546E7A', 'Diseña máquinas y sistemas térmicos: mecánica, materiales, termodinámica, fluidos, diseño de elementos, manufactura y mantenimiento.', 89900, 5, '[{"title": "Física universitaria volumen 1 (libro gratuito en español)", "publisher": "OpenStax – Rice University", "url": "https://openstax.org/details/books/f%C3%ADsica-universitaria-volumen-1", "use": "Mecánica y física para ingenieros"}, {"title": "MIT OpenCourseWare", "publisher": "Massachusetts Institute of Technology", "url": "https://ocw.mit.edu/", "use": "Cursos universitarios gratuitos de ingeniería"}]'::jsonb, null),
  ('ingenieria-mecatronica', 'Ingeniería Mecatrónica', 'Ingeniería', '#00695C', 'Integra mecánica, electrónica, control y software: sensores, actuadores, PLC, robótica industrial, visión artificial y sistemas automáticos.', 89900, 5, '[{"title": "Documentación de Arduino", "publisher": "Arduino", "url": "https://docs.arduino.cc/", "use": "Microcontroladores y prototipos"}, {"title": "International Federation of Robotics", "publisher": "IFR", "url": "https://ifr.org/", "use": "Estadísticas y tendencias de robótica"}, {"title": "Documentación de OpenCV", "publisher": "OpenCV", "url": "https://docs.opencv.org/4.x/", "use": "Visión artificial"}]'::jsonb, null),
  ('ingenieria-ambiental', 'Ingeniería Ambiental', 'Ingeniería', '#2E7D32', 'Resuelve problemas ambientales con ingeniería: tratamiento de agua, aire, residuos, suelos, evaluación de impacto, normatividad y gestión ambiental.', 89900, 5, '[{"title": "IDEAM", "publisher": "Instituto de Hidrología, Meteorología y Estudios Ambientales", "url": "https://www.ideam.gov.co/", "use": "Clima, agua y datos ambientales"}, {"title": "ANLA", "publisher": "Autoridad Nacional de Licencias Ambientales", "url": "https://www.anla.gov.co/", "use": "Licenciamiento ambiental"}, {"title": "Ley 99 de 1993", "publisher": "Secretaría del Senado de Colombia", "url": "http://www.secretariasenado.gov.co/senado/basedoc/ley_0099_1993.html", "use": "Sistema Nacional Ambiental"}]'::jsonb, null),
  ('ingenieria-quimica', 'Ingeniería Química', 'Ingeniería', '#7B1FA2', 'Transforma materias primas en productos útiles: balances, termodinámica, fenómenos de transporte, operaciones unitarias, reactores y diseño de plantas.', 89900, 5, '[{"title": "Química 2ed (libro gratuito en español)", "publisher": "OpenStax – Rice University", "url": "https://openstax.org/details/books/qu%C3%ADmica-2ed", "use": "Química general"}, {"title": "Tabla periódica de los elementos", "publisher": "IUPAC", "url": "https://iupac.org/what-we-do/periodic-table-of-elements/", "use": "Elementos químicos"}, {"title": "MIT OpenCourseWare", "publisher": "Massachusetts Institute of Technology", "url": "https://ocw.mit.edu/", "use": "Cursos universitarios gratuitos de ingeniería"}]'::jsonb, null),
  ('ingenieria-biomedica', 'Ingeniería Biomédica', 'Ingeniería', '#C2185B', 'Aplica la ingeniería a la salud: biomecánica, bioinstrumentación, imágenes médicas, biomateriales, dispositivos médicos y gestión tecnológica hospitalaria.', 89900, 5, '[{"title": "INVIMA", "publisher": "Instituto Nacional de Vigilancia de Medicamentos y Alimentos", "url": "https://www.invima.gov.co/", "use": "Medicamentos, dispositivos y alimentos"}, {"title": "Dispositivos médicos", "publisher": "OMS", "url": "https://www.who.int/health-topics/medical-devices", "use": "Regulación y acceso a dispositivos"}, {"title": "NCBI", "publisher": "Biblioteca Nacional de Medicina de EE. UU.", "url": "https://www.ncbi.nlm.nih.gov/", "use": "Literatura científica biomédica"}]'::jsonb, null),
