  ('ingenieria-aeroespacial', 'Ingeniería Aeroespacial', 'Ingeniería', '#1A237E', 'Explora cómo vuelan aviones, cohetes y satélites: aerodinámica, propulsión, estructuras, mecánica orbital, aviónica y diseño de vehículos.', 89900, 5, '[{"title": "Beginner''s Guide to Aeronautics", "publisher": "NASA Glenn Research Center", "url": "https://www.grc.nasa.gov/www/k-12/airplane/", "use": "Aerodinámica y propulsión"}, {"title": "NASA Science", "publisher": "NASA", "url": "https://science.nasa.gov/", "use": "Ciencia y misiones espaciales"}, {"title": "Aeronáutica Civil de Colombia", "publisher": "Gobierno de Colombia", "url": "https://www.aerocivil.gov.co/", "use": "Regulación aeronáutica"}]'::jsonb, null),
  ('ingenieria-de-minas', 'Ingeniería de Minas', 'Ingeniería', '#4E342E', 'Explora, extrae y procesa minerales de forma segura y responsable: geología, exploración, minería a cielo abierto y subterránea, metalurgia y cierre de minas.', 89900, 5, '[{"title": "Agencia Nacional de Minería", "publisher": "Gobierno de Colombia", "url": "https://www.anm.gov.co/", "use": "Títulos y fiscalización minera"}, {"title": "Geología de Colombia (libro)", "publisher": "Servicio Geológico Colombiano", "url": "https://www2.sgc.gov.co/LibroGeologiaColombia/Paginas/Inicio.aspx", "use": "Geología del territorio colombiano"}, {"title": "UPME", "publisher": "Unidad de Planeación Minero Energética", "url": "https://www.upme.gov.co/", "use": "Planeación energética y minera"}]'::jsonb, null),
